import{H as e,_t as t,nt as n,rt as r}from"./chunks/framework.ByJSXnli.js";var i=JSON.parse(`{"title":"Architecture overview","description":"","frontmatter":{},"headers":[],"relativePath":"contributing/architecture/index.md","filePath":"contributing/architecture/index.md"}`),a={name:`contributing/architecture/index.md`};function o(e,i,a,o,s,c){return t(),n(`div`,null,[...i[0]||=[r(`<h1 id="architecture-overview" tabindex="-1">Architecture overview <a class="header-anchor" href="#architecture-overview" aria-label="Permalink to “Architecture overview”">​</a></h1><p>HeuristicLib separates what to run from running it. Configurations are immutable descriptions, and a run builds executors from them that hold all mutable state. Everything else follows from that split.</p><h2 id="the-parts" tabindex="-1">The parts <a class="header-anchor" href="#the-parts" aria-label="Permalink to “The parts”">​</a></h2><div class="doc-table-scroll" tabindex="0"><table><thead><tr><th>Part</th><th>Responsibility</th><th>Read</th></tr></thead><tbody><tr><td>Layers</td><td>Which type may depend on which, and who owns a run</td><td><a href="/contributing/architecture/layering.html">Layering</a></td></tr><tr><td>Execution nodes</td><td>What configurations, executors and run results own, and how they are constructed</td><td><a href="/contributing/architecture/execution-nodes.html">Execution nodes</a></td></tr><tr><td>Resolution</td><td>How a scope builds, keeps and shares executors, and how substitutions order wrappers</td><td><a href="/contributing/architecture/execution-resolution.html">Execution resolution</a></td></tr><tr><td>Operators</td><td>The rules behind the operator bases, routing and new roles</td><td><a href="/contributing/architecture/operator-implementation.html">Operator implementation</a></td></tr><tr><td>Analysis</td><td>Observation boundaries, clocks, traces and the ownership of analyzer results</td><td><a href="/contributing/architecture/analyzers.html">Analyzer architecture</a></td></tr></tbody></table></div><h2 id="from-configuration-to-result" tabindex="-1">From configuration to result <a class="header-anchor" href="#from-configuration-to-result" aria-label="Permalink to “From configuration to result”">​</a></h2><ol><li>A user builds a configuration graph from algorithm and operator records. Each record declares its settings and children as parameters.</li><li><code>Substitute</code> and the substitutions passed to <code>CreateRun</code> rewrite the graph, for example to place an analyzer&#39;s observation wrapper.</li><li>Validation walks the declared parameters and checks the run types and the invariants of every configuration.</li><li><code>AlgorithmRun</code> creates a root resolution scope. On the first advance the scope calls the algorithm&#39;s construction hook, which resolves its children through the scope.</li><li>Executors run the search. Observation wrappers report to analyzers, which write into run results owned by the root scope.</li><li>The caller reads the results through <code>run.Result</code>.</li></ol><p><a href="/extend/how-execution-works.html">How execution works</a> describes the same flow for component authors.</p><h2 id="principles-that-shape-the-code" tabindex="-1">Principles that shape the code <a class="header-anchor" href="#principles-that-shape-the-code" aria-label="Permalink to “Principles that shape the code”">​</a></h2><ul><li><strong>No privileges for built-in operations.</strong> A user-defined operation is resolved, wrapped, observed and traced exactly like a built-in one. Nothing lists the built-in operations.</li><li><strong>Configurations hold no state.</strong> State lives in executors and run results, so one configuration serves many runs at once.</li><li><strong>Declared parameters are the graph.</strong> Validation, substitution and sharing reach a child only through its declaration.</li><li><strong>Run results belong to the run.</strong> Analyzers are configurations and keep no data themselves.</li></ul><p><a href="/contributing/design-goals.html">Design goals</a> and the <a href="/contributing/developer-guidelines.html">developer guidelines</a> state these principles in full.</p>`,10)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};